-- SINH TỰ ĐỘNG — KHÔNG SỬA TAY.
-- Nguồn: backend/app/semantic/feature_spec.py + backend/scripts/generate_dbt_models.py
-- Sinh lại:  cd backend && python -m scripts.generate_dbt_models
--
-- Bản nháp của feature.gsm_transaction. dbt test chạy TRÊN BẢNG NÀY, trước khi
-- publish_gold.py ghi sang feature.* — CHECK constraint của bảng gold sẽ từ chối
-- INSERT trước khi test kịp chạy nếu đặt test ở đó. 167 cột feature.
--
-- alias trùng tên bảng gold để `parity_check --source dbt_work` so thẳng candidate với
-- baseline mà không cần bảng ánh xạ tên. Schema thì vẫn là dbt_work — dbt không có
-- quyền DDL trên feature.*, việc ghi sang đó là của publish_gold.py.
{{ config(alias='gsm_transaction') }}

select
    s.customer_id,
    s.snapshot_date,
    max(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 0 and t.status_group = 'canceled') as canceled_original_price_max_daily,
    max(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 364 and t.status_group = 'canceled') as canceled_original_price_max_l12m,
    max(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 29 and t.status_group = 'canceled') as canceled_original_price_max_l1m,
    max(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 6 and t.status_group = 'canceled') as canceled_original_price_max_l1w,
    max(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 13 and t.status_group = 'canceled') as canceled_original_price_max_l2w,
