    max(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 179 and t.status_group = 'canceled') as canceled_original_price_max_l6m,
    coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 0 and t.status_group = 'canceled'), 0) as canceled_original_price_sum_daily,
    coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 364 and t.status_group = 'canceled'), 0) as canceled_original_price_sum_l12m,
