    coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 13 and t.status_group = 'canceled'), 0) as canceled_original_price_sum_l2w,
    coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 89 and t.status_group = 'canceled'), 0) as canceled_original_price_sum_l3m,
    coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 179 and t.status_group = 'canceled'), 0) as canceled_original_price_sum_l6m,
