    count(distinct t.trip_date) filter (where t.trip_date >= s.snapshot_date - 29 and t.status_group = 'canceled') as canceled_txn_active_day_count_l1m,
    count(distinct t.trip_date) filter (where t.trip_date >= s.snapshot_date - 6 and t.status_group = 'canceled') as canceled_txn_active_day_count_l1w,
    count(distinct t.trip_date) filter (where t.trip_date >= s.snapshot_date - 13 and t.status_group = 'canceled') as canceled_txn_active_day_count_l2w,
    count(distinct t.trip_date) filter (where t.trip_date >= s.snapshot_date - 89 and t.status_group = 'canceled') as canceled_txn_active_day_count_l3m,
    count(distinct t.trip_date) filter (where t.trip_date >= s.snapshot_date - 179 and t.status_group = 'canceled') as canceled_txn_active_day_count_l6m,
    count(*) filter (where t.trip_date >= s.snapshot_date - 0 and t.status_group = 'canceled') as canceled_txn_count_daily,
    count(*) filter (where t.trip_date >= s.snapshot_date - 364 and t.status_group = 'canceled') as canceled_txn_count_l12m,
    count(*) filter (where t.trip_date >= s.snapshot_date - 29 and t.status_group = 'canceled') as canceled_txn_count_l1m,
    count(*) filter (where t.trip_date >= s.snapshot_date - 6 and t.status_group = 'canceled') as canceled_txn_count_l1w,
    count(*) filter (where t.trip_date >= s.snapshot_date - 13 and t.status_group = 'canceled') as canceled_txn_count_l2w,
