    coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 6 and t.status_group = 'canceled' and t.is_weekday), 0) as canceled_weekday_original_price_sum_l1w,
    coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 13 and t.status_group = 'canceled' and t.is_weekday), 0) as canceled_weekday_original_price_sum_l2w,
    coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 89 and t.status_group = 'canceled' and t.is_weekday), 0) as canceled_weekday_original_price_sum_l3m,
    coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 179 and t.status_group = 'canceled' and t.is_weekday), 0) as canceled_weekday_original_price_sum_l6m,
    count(*) filter (where t.trip_date >= s.snapshot_date - 364 and t.status_group = 'canceled' and t.is_weekday) as canceled_weekday_txn_count_l12m,
    count(*) filter (where t.trip_date >= s.snapshot_date - 29 and t.status_group = 'canceled' and t.is_weekday) as canceled_weekday_txn_count_l1m,
    count(*) filter (where t.trip_date >= s.snapshot_date - 6 and t.status_group = 'canceled' and t.is_weekday) as canceled_weekday_txn_count_l1w,
    count(*) filter (where t.trip_date >= s.snapshot_date - 13 and t.status_group = 'canceled' and t.is_weekday) as canceled_weekday_txn_count_l2w,
    count(*) filter (where t.trip_date >= s.snapshot_date - 89 and t.status_group = 'canceled' and t.is_weekday) as canceled_weekday_txn_count_l3m,
    count(*) filter (where t.trip_date >= s.snapshot_date - 179 and t.status_group = 'canceled' and t.is_weekday) as canceled_weekday_txn_count_l6m,
    coalesce(sum(t.discount_amount) filter (where t.trip_date >= s.snapshot_date - 0 and t.status_group = 'completed'), 0) as completed_discount_amount_sum_daily,
    coalesce(sum(t.discount_amount) filter (where t.trip_date >= s.snapshot_date - 364 and t.status_group = 'completed'), 0) as completed_discount_amount_sum_l12m,
    coalesce(sum(t.discount_amount) filter (where t.trip_date >= s.snapshot_date - 29 and t.status_group = 'completed'), 0) as completed_discount_amount_sum_l1m,
