    coalesce(sum(t.discount_amount) filter (where t.trip_date >= s.snapshot_date - 179 and t.status_group = 'completed'), 0) as completed_discount_amount_sum_l6m,
    max(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 0 and t.status_group = 'completed') as completed_original_price_max_daily,
    max(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 364 and t.status_group = 'completed') as completed_original_price_max_l12m,
    max(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 29 and t.status_group = 'completed') as completed_original_price_max_l1m,
    max(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 6 and t.status_group = 'completed') as completed_original_price_max_l1w,
    max(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 13 and t.status_group = 'completed') as completed_original_price_max_l2w,
    max(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 89 and t.status_group = 'completed') as completed_original_price_max_l3m,
    max(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 179 and t.status_group = 'completed') as completed_original_price_max_l6m,
    coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 0 and t.status_group = 'completed'), 0) as completed_original_price_sum_daily,
    coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 364 and t.status_group = 'completed'), 0) as completed_original_price_sum_l12m,
    coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 29 and t.status_group = 'completed'), 0) as completed_original_price_sum_l1m,
    case when (coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 89 and t.status_group = 'completed'), 0)) <> 0 then round(((coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 29 and t.status_group = 'completed'), 0))::float8 / (coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 89 and t.status_group = 'completed'), 0))::float8) * 10000) / 10000 end as completed_original_price_sum_l1m_vs_l3m,
    case when (coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 179 and t.status_group = 'completed'), 0)) <> 0 then round(((coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 29 and t.status_group = 'completed'), 0))::float8 / (coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 179 and t.status_group = 'completed'), 0))::float8) * 10000) / 10000 end as completed_original_price_sum_l1m_vs_l6m,
    coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 6 and t.status_group = 'completed'), 0) as completed_original_price_sum_l1w,
