    case when (round(coalesce(sum(t.distance_km) filter (where t.trip_date >= s.snapshot_date - 179 and t.status_group = 'completed'), 0), 2)) <> 0 then round(((round(coalesce(sum(t.distance_km) filter (where t.trip_date >= s.snapshot_date - 29 and t.status_group = 'completed'), 0), 2))::float8 / (round(coalesce(sum(t.distance_km) filter (where t.trip_date >= s.snapshot_date - 179 and t.status_group = 'completed'), 0), 2))::float8) * 10000) / 10000 end as completed_trip_distance_km_sum_l1m_vs_l6m,
