    count(*) filter (where t.trip_date >= s.snapshot_date - 0 and t.status_group = 'completed' and t.is_daytime) as finished_time_daytime_txn_count_daily,
    count(*) filter (where t.trip_date >= s.snapshot_date - 364 and t.status_group = 'completed' and t.is_daytime) as finished_time_daytime_txn_count_l12m,
    count(*) filter (where t.trip_date >= s.snapshot_date - 29 and t.status_group = 'completed' and t.is_daytime) as finished_time_daytime_txn_count_l1m,
    count(*) filter (where t.trip_date >= s.snapshot_date - 6 and t.status_group = 'completed' and t.is_daytime) as finished_time_daytime_txn_count_l1w,
    count(*) filter (where t.trip_date >= s.snapshot_date - 13 and t.status_group = 'completed' and t.is_daytime) as finished_time_daytime_txn_count_l2w,
    count(*) filter (where t.trip_date >= s.snapshot_date - 89 and t.status_group = 'completed' and t.is_daytime) as finished_time_daytime_txn_count_l3m,
    count(*) filter (where t.trip_date >= s.snapshot_date - 179 and t.status_group = 'completed' and t.is_daytime) as finished_time_daytime_txn_count_l6m,
    count(distinct t.trip_date) filter (where t.trip_date >= s.snapshot_date - 0 and t.status_group = 'completed') as finished_txn_active_day_count_daily,
    count(distinct t.trip_date) filter (where t.trip_date >= s.snapshot_date - 364 and t.status_group = 'completed') as finished_txn_active_day_count_l12m,
    count(distinct t.trip_date) filter (where t.trip_date >= s.snapshot_date - 29 and t.status_group = 'completed') as finished_txn_active_day_count_l1m,
    count(distinct t.trip_date) filter (where t.trip_date >= s.snapshot_date - 6 and t.status_group = 'completed') as finished_txn_active_day_count_l1w,
    count(distinct t.trip_date) filter (where t.trip_date >= s.snapshot_date - 13 and t.status_group = 'completed') as finished_txn_active_day_count_l2w,
    count(distinct t.trip_date) filter (where t.trip_date >= s.snapshot_date - 89 and t.status_group = 'completed') as finished_txn_active_day_count_l3m,
    count(distinct t.trip_date) filter (where t.trip_date >= s.snapshot_date - 179 and t.status_group = 'completed') as finished_txn_active_day_count_l6m,
    count(*) filter (where t.trip_date >= s.snapshot_date - 0 and t.status_group = 'completed') as finished_txn_count_daily,
    count(*) filter (where t.trip_date >= s.snapshot_date - 364 and t.status_group = 'completed') as finished_txn_count_l12m,
    count(*) filter (where t.trip_date >= s.snapshot_date - 29 and t.status_group = 'completed') as finished_txn_count_l1m,
    case when (count(*) filter (where t.trip_date >= s.snapshot_date - 89 and t.status_group = 'completed')) <> 0 then round(((count(*) filter (where t.trip_date >= s.snapshot_date - 29 and t.status_group = 'completed'))::float8 / (count(*) filter (where t.trip_date >= s.snapshot_date - 89 and t.status_group = 'completed'))::float8) * 10000) / 10000 end as finished_txn_count_l1m_vs_l3m,
    case when (count(*) filter (where t.trip_date >= s.snapshot_date - 179 and t.status_group = 'completed')) <> 0 then round(((count(*) filter (where t.trip_date >= s.snapshot_date - 29 and t.status_group = 'completed'))::float8 / (count(*) filter (where t.trip_date >= s.snapshot_date - 179 and t.status_group = 'completed'))::float8) * 10000) / 10000 end as finished_txn_count_l1m_vs_l6m,
    count(*) filter (where t.trip_date >= s.snapshot_date - 6 and t.status_group = 'completed') as finished_txn_count_l1w,
    count(*) filter (where t.trip_date >= s.snapshot_date - 13 and t.status_group = 'completed') as finished_txn_count_l2w,
    count(*) filter (where t.trip_date >= s.snapshot_date - 89 and t.status_group = 'completed') as finished_txn_count_l3m,
    case when (count(*) filter (where t.trip_date >= s.snapshot_date - 364 and t.status_group = 'completed')) <> 0 then round(((count(*) filter (where t.trip_date >= s.snapshot_date - 89 and t.status_group = 'completed'))::float8 / (count(*) filter (where t.trip_date >= s.snapshot_date - 364 and t.status_group = 'completed'))::float8) * 10000) / 10000 end as finished_txn_count_l3m_vs_l12m,
    count(*) filter (where t.trip_date >= s.snapshot_date - 179 and t.status_group = 'completed') as finished_txn_count_l6m,
    count(*) filter (where t.trip_date >= s.snapshot_date - 6 and t.status_group = 'completed' and t.service_type = 'bike') as finished_type_bike_txn_count_l1w,
    count(*) filter (where t.trip_date >= s.snapshot_date - 13 and t.status_group = 'completed' and t.service_type = 'bike') as finished_type_bike_txn_count_l2w,
    count(*) filter (where t.trip_date >= s.snapshot_date - 6 and t.status_group = 'completed' and t.service_type = 'express') as finished_type_express_txn_count_l1w,
    count(*) filter (where t.trip_date >= s.snapshot_date - 13 and t.status_group = 'completed' and t.service_type = 'express') as finished_type_express_txn_count_l2w,
    count(*) filter (where t.trip_date >= s.snapshot_date - 6 and t.status_group = 'completed' and t.service_type = 'food') as finished_type_food_txn_count_l1w,
    count(*) filter (where t.trip_date >= s.snapshot_date - 13 and t.status_group = 'completed' and t.service_type = 'food') as finished_type_food_txn_count_l2w,
    count(*) filter (where t.trip_date >= s.snapshot_date - 6 and t.status_group = 'completed' and t.service_type = 'taxi') as finished_type_taxi_txn_count_l1w,
    count(*) filter (where t.trip_date >= s.snapshot_date - 13 and t.status_group = 'completed' and t.service_type = 'taxi') as finished_type_taxi_txn_count_l2w,
    coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 364 and t.status_group = 'completed' and t.is_weekday), 0) as finished_weekday_original_price_sum_l12m,
    coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 29 and t.status_group = 'completed' and t.is_weekday), 0) as finished_weekday_original_price_sum_l1m,
    coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 6 and t.status_group = 'completed' and t.is_weekday), 0) as finished_weekday_original_price_sum_l1w,
    coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 13 and t.status_group = 'completed' and t.is_weekday), 0) as finished_weekday_original_price_sum_l2w,
    coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 89 and t.status_group = 'completed' and t.is_weekday), 0) as finished_weekday_original_price_sum_l3m,
    coalesce(sum(t.total_fare) filter (where t.trip_date >= s.snapshot_date - 179 and t.status_group = 'completed' and t.is_weekday), 0) as finished_weekday_original_price_sum_l6m,
    count(*) filter (where t.trip_date >= s.snapshot_date - 364 and t.status_group = 'completed' and t.is_weekday) as finished_weekday_txn_count_l12m,
    count(*) filter (where t.trip_date >= s.snapshot_date - 29 and t.status_group = 'completed' and t.is_weekday) as finished_weekday_txn_count_l1m,
    count(*) filter (where t.trip_date >= s.snapshot_date - 6 and t.status_group = 'completed' and t.is_weekday) as finished_weekday_txn_count_l1w,
    count(*) filter (where t.trip_date >= s.snapshot_date - 13 and t.status_group = 'completed' and t.is_weekday) as finished_weekday_txn_count_l2w,
    count(*) filter (where t.trip_date >= s.snapshot_date - 89 and t.status_group = 'completed' and t.is_weekday) as finished_weekday_txn_count_l3m,
    count(*) filter (where t.trip_date >= s.snapshot_date - 179 and t.status_group = 'completed' and t.is_weekday) as finished_weekday_txn_count_l6m
from {{ ref('silver_customer_snapshot') }} s
left join {{ ref('silver_gsm_trip') }} t
       on t.customer_id = s.customer_id
      and t.trip_date <= s.snapshot_date
group by s.customer_id, s.snapshot_date
